func TestEnumHarborPipelineStatusResponseType(t *testing.T) {
	t.Run("NewFromString_bulk", func(t *testing.T) {
		t.Parallel()
		val, err := NewHarborPipelineStatusResponseTypeFromString("bulk")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, HarborPipelineStatusResponseType("bulk"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_model", func(t *testing.T) {
		t.Parallel()
		val, err := NewHarborPipelineStatusResponseTypeFromString("model")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, HarborPipelineStatusResponseType("model"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_Invalid", func(t *testing.T) {
		_, err := NewHarborPipelineStatusResponseTypeFromString("invalid_value_that_does_not_exist")
		assert.Error(t, err)
	})

	t.Run("Ptr", func(t *testing.T) {
		val, err := NewHarborPipelineStatusResponseTypeFromString("bulk")
		assert.NoError(t, err)
		ptr := val.Ptr()
		assert.NotNil(t, ptr)
		assert.Equal(t, val, *ptr)
	})
}

